reportText:
{
  "findings": [
    {
      "file": "src/api.js",
      "what": "请求的是 /api/v1/users/:id，但路由表（src/routes.js）只注册了 /api/v2 版本，接口版本不匹配会 404"
    },
    {
      "file": "src/async.js",
      "what": "xs.map 返回的是 Promise 数组而非结果（漏掉 Promise.all），且 f 未定义会抛 ReferenceError"
    },
    {
      "file": "src/cache.js",
      "what": "put 只写入不删除，没有过期机制，缓存条目永不过期导致内存泄漏"
    },
    {
      "file": "src/conn.js",
      "what": "pool 为空时 shift() 返回 undefined，没有检查空池，调用方拿到 undefined 会出错"
    },
    {
      "file": "src/copy.js",
      "what": "clone 只做对象展开的浅拷贝，嵌套对象仍共享引用，并非深拷贝"
    },
    {
      "file": "src/listen.js",
      "what": "on 没有返回取消订阅的函数，监听器无法被移除，造成监听泄漏"
    },
    {
      "file": "src/money.js",
      "what": "用 === 直接比较浮点金额，0.1+0.2 这类值会被误判为不相等"
    },
    {
      "file": "src/parse.js",
      "what": "parseInt 没传基数，'0x1A' 这类字符串会被按十六进制解析出错误结果"
    },
    {
      "file": "src/reader.js",
      "what": "return 之前忘了 closeSync(fd)，文件描述符泄漏"
    },
    {
      "file": "src/retry.js",
      "what": "3 次重试全部失败后静默返回 undefined，异常被吞掉，调用方无法感知失败"
    },
    {
      "file": "src/sort.js",
      "what": "sort 默认按字符串比较，数字会按字典序排错（10 排在 2 前面）"
    },
    {
      "file": "src/stats.js",
      "what": "循环条件 i <= arr.length 越界（应为 <），会读到数组之外的 undefined"
    }
  ]
}
